import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpiryTest {

    // 2026-11-15 12:00 UTC is 13:00 in Warsaw.
    private static final Clock NOW = Clock.fixed(Instant.parse("2026-11-15T12:00:00Z"), ZoneOffset.UTC);

    private final OrderRepository orders = new OrderRepository();
    private final OrderService service = new OrderService(orders, NOW);

    private void place(String id, String placedAt, String status) {
        Order order = new Order(id, "c-1", Money.pln(1000), Instant.parse(placedAt));
        order.changeStatus(status);
        orders.save(order);
    }

    @Test
    void cancelsPlacedOrdersOlderThanThirtyDays() {
        place("old", "2026-10-01T10:00:00Z", "PLACED");

        assertEquals(1, service.expireStale());
        assertEquals("CANCELLED", orders.get("old").status());
    }

    @Test
    void leavesOrdersPlacedWithinThirtyDays() {
        place("recent", "2026-10-20T10:00:00Z", "PLACED");

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", orders.get("recent").status());
    }

    @Test
    void leavesOrdersThatAreNotPlaced() {
        place("confirmed", "2026-10-01T10:00:00Z", "CONFIRMED");
        place("cancelled", "2026-10-01T10:00:00Z", "CANCELLED");

        assertEquals(0, service.expireStale());
        assertEquals("CONFIRMED", orders.get("confirmed").status());
        assertEquals("CANCELLED", orders.get("cancelled").status());
    }

    @Test
    void thirtyDaysExactlyIsNotMoreThanThirtyDays() {
        // 2026-10-16 is 30 days before 2026-11-15 in Warsaw.
        place("boundary", "2026-10-16T10:00:00Z", "PLACED");

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", orders.get("boundary").status());
    }

    @Test
    void usesTheWarsawCalendarDay() {
        // 2026-10-15 22:30 UTC is already 2026-10-16 in Warsaw (CEST), so it is 30 days old, not 31.
        place("late-evening", "2026-10-15T22:30:00Z", "PLACED");

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", orders.get("late-evening").status());
    }

    @Test
    void countsOnlyTheOrdersItCancelled() {
        place("a", "2026-09-01T10:00:00Z", "PLACED");
        place("b", "2026-09-02T10:00:00Z", "PLACED");
        place("c", "2026-11-10T10:00:00Z", "PLACED");

        assertEquals(2, service.expireStale());
        assertEquals(0, service.expireStale());
    }
}
}
